/**
 * Thunderhead Pass, Cloudreach's course. Data only: the level format is documented in `level/parse.ts`.
 * Only `courses/index.ts` imports this file.
 */
import type { LevelDef } from '../types.ts';
import type { CourseSection, ShippedCourse } from './types.ts';

/**
 * Thunderhead Pass, flown left to right. Rows 0 and 25 are the ceiling and the floor; flight reads
 * `#` as thunderhead, `C` as puff cloud, `~` as fog, `>` `<` as gusts, `^` `v` as updrafts and
 * downdrafts, `B` as a bounce cloud, `@` as a boost ring, `o` as a feather, `?` as a balloon, `*` as
 * a spark cloud, `j` as a static wisp, `S` as a storm crow, `E` as a sky eel and `K` as a cloud crab.
 *
 * - Cols 1-190, the cloud bank: the starts, a puff cluster (19-21) to pop or fly round, a low fog
 *   bank under a high gust on rows 4-5 (28-46), an overhang down to row 22 (50-56) that brings the
 *   way to the floor right over a bounce cloud (57-59) at the foot of a 17-row thunderhead wall
 *   (60-63) with a cloud crab on top; then towers up and down, floor gaps out of the bottom of the
 *   sky at 95-100 (a tailwind on rows 10-11 over it) and 146-151 (a headwind on rows 18-19 by the
 *   second), a balloon over the way at 114, a puff column at 118-119 to pop or fly over, a
 *   thunderhead block with a crab on it (126-134), spark clouds and a mid-height fog bank
 *   (170-178).
 * - Cols 192-410, the high road over the low road: a thunderhead shelf on rows 12-13 splits the sky.
 *   Above it, under a thunderhead ceiling on rows 1-2 (200-405), a tailwind on rows 5-7 with two
 *   boost-ring lines on row 6 (206-222, 316-332), where the way runs, so a flyer who holds altitude
 *   takes them; balloons at 236, 300 and 356, and storm crows and static wisps patrol it. Between
 *   the ring lines a shifting wind zone (250-289) over both roads turns the gust round every 3 s.
 *   Below it, the sheltered low road: fog banks and updrafts lifting over thunderhead mounds,
 *   slower and with no enemies or gaps.
 * - Cols 412-736, Sunbreak: an open stretch along sunlit cloudbanks (s). The ring line first
 *   dips gently, then dives farther and climbs higher; the deepest dip leads into the spring
 *   clouds at 595-610. One last wave rides over the lit cloudbanks at 657-675 and 693-711.
 *   Feathers show the entry into each arc and balloons sit off the fast line.
 * - Cols 737-1138, the crow cliffs: climb the first step on the updraft at 758-766, then weave
 *   between rising shelves, overhangs and puff plugs. The roosts (r) are at 829-844, 862-889
 *   and 1012-1030. After the first summit, duck below the overhangs at 896-912, 935-943 and
 *   973-983 before the next perch; the feather line shows the long dive into the cannon approach.
 *   The slower tunnel below the shelves has a solid floor and fog banks (eel at 844).
 * - Cols 1139-1568, the cannon clouds: a lone barrel at 1151 shoots across the open floor
 *   at 1156-1195. The upper feather line and updrafts give flyers who miss it a slower crossing.
 *   Gantries (g) at 1237-1248 mark a battery: the upper barrel hands off to a level shot through
 *   six rings, the middle barrel commits to the timed crossing at 1252-1255, and the lower barrel
 *   drops toward springs where a flyer can wait for a calm crossing. The relay at 1301 and 1312
 *   turns a diagonal climb into a flat shot through the ring line over the shelf. The low tunnel
 *   bypasses it.
 *   The exit winds under a mooring deck at 1362-1380, then over or under the finishing gantries.
 * - Cols 1569-1772, the storm cell: three lightning zones with offset periods (1583-1586,
 *   1607-1612, 1655-1659), downdrafts (1587-1590, 1661-1665), a sky eel in a ceiling pillar
 *   (1601), and a thunderhead block (1633-1651) whose low tunnel is plugged by a puff-cloud
 *   wall (1639-1640) a dash breaks, the shortcut under the climb over its top; then towers,
 *   a low tailwind on rows 16-18 (1679-1717), a spark cloud and a floor gap (1685-1690).
 * - Cols 1773-1813, the finish straight: a tailwind on rows 12-13 and a feather line; the finish
 *   is col 1814.
 */
