/** Joins the 26 rows of each section after checking its shape. */
function joinSections(parts: readonly string[]): string {
  const height = 26;
  const sections = parts.map((part, i) => {
    const rows = part
      .trim()
      .split('\n')
      .map((row) => row.trim());
    if (rows.length !== height) throw new Error(`Section ${i} has ${rows.length} rows, expected ${height}`);
    const width = rows[0]?.length;
    rows.forEach((row, y) => {
      if (row.length !== width) throw new Error(`Section ${i} row ${y} has ${row.length} columns, expected ${width}`);
    });
    return rows;
  });
  return Array.from({ length: height }, (_, y) => sections.map((section) => section[y]).join('')).join('\n');
}

